const { createHash } = require('node:crypto');

const Settings = require('./settings.js');

// Tokens are generated by the client and act as a bearer secret. Anything that
// looks random enough is accepted; the public username is a hash of the token.
const TOKEN_PATTERN = /^[A-Za-z0-9_-]{16,128}$/;

function isValidToken(token) {
    return typeof token === 'string' && TOKEN_PATTERN.test(token);
}

/**
 * Builds the throwaway user for a client token, or undefined if the token is
 * not acceptable.
 *
 * @param {unknown} token
 */
function userFromToken(token) {
    if (!isValidToken(token)) {
        return undefined;
    }

    const username = `Guest-${createHash('sha256').update(token).digest('hex').slice(0, 6)}`;

    return Settings.getUserWithDefaultsSet({
        username,
        settings: { optionSettings: { orderForcedAbilities: true } }
    });
}

module.exports = { isValidToken, userFromToken };
